(110,	'App\\User',	3,	'created',	'App\\Track',	1701,	'[]',	'{\"artists\":\"Dariya Letto\",\"name\":\"Travel\",\"mix_name\":\"Original Mix\",\"remixers\":\"[\\\"\\\"]\",\"composer\":\"KEBA DARIA MYKOLAEVNA\",\"isrc\":\"UA-CT1-23-00038\",\"genre\":\"Orchestral, Cinematic\",\"youtube\":null,\"bpm\":null,\"length\":null,\"beatport_id\":null,\"beatport_slug\":null,\"beatport_release_id\":null,\"beatport_wave\":null,\"beatport_sample\":null,\"beatport_sample_start\":null,\"beatport_sample_end\":null,\"id\":1701}',	'https://cts-label.com/cts-admin/tracks',	'109.95.53.115',	'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/109.0.0.0 Safari/537.36',	NULL,	'2023-09-27 18:29:12',	'2023-09-27 18:29:12'),
(111,	'App\\User',	3,	'created',	'App\\Release',	1877,	'[]',	'{\"tracklist_show_artist\":\"1\",\"tracklist_show_title\":\"1\",\"tracklist_show_mix\":\"1\",\"visible\":true,\"title\":\"Dariya Letto - The Will To Win\",\"genre\":\"Orchestral, Cinematic\",\"release_number\":\"CPR001233\",\"exclusive_period\":\"No Exclusive Period\",\"beatport\":null,\"youtube\":null,\"tracklist_show_custom\":\"0\",\"tracklist\":null,\"description_en\":\"<p>CTS Records presents new label dedicated strictly to cinematic music. Orchestral and instrumental, ambient and electronica genres are distinguished by the Cinema Puls Records music direction, the main thing that unites all these genres is the cinematic images that the authors create in their music.<br>With it\\u2019s first release Cinema Puls Records would like to announce brand new mini-album by Ukrainian film score composer Dariya Letto. While studying music Dariya took lessons from the famous Ukrainian composer Volodymyr Stetsenko, who helped her to define the direction of music as cinematic and to enhance the emotional expressiveness and drama of her musical images. Being a passionate about the inseparability of music and video Dariya worked on computer games sound design. This passion later naturally led the composer to create music for films and her works were taken to detective series soundtrack. Nowadays composer in her creativity turns to music that combines the electronic sound with traditional orchestral arrangements. Despite of hard circumstances of &nbsp;war in Ukraine Daria Letto continue her musical search. She is open to finding new soundings and innovations in her work at the same time her music is still continue to be fulfilled with bright cinematic images. Mini-album includes four new works which, complementing each other, create the overall cohesive mood of the album.<\\/p>\",\"description_ru\":null,\"description_ua\":null,\"uploaded_on_beatport\":\"0\",\"uploaded_on_believe\":\"0\",\"uploaded_on_juno\":\"0\",\"uploaded_on_google_drive\":\"0\",\"label_copy_uploaded\":\"0\",\"promo_upload\":\"0\",\"uploaded_on_zip_dj\":\"0\",\"uploaded_on_music_worx\":\"0\",\"uploaded_on_release_promo\":\"0\",\"is_emailing_done\":\"0\",\"release_date\":\"2023-10-05 00:00:00\",\"sort_id\":379,\"image\":\"-dariya-letto-the-will-to-win_500.jpg\",\"image_270\":\"-dariya-letto-the-will-to-win_270.jpg\",\"id\":1877}',	'https://cts-label.com/cts-admin/releases',	'109.95.53.115',	'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/109.0.0.0 Safari/537.36',	NULL,	'2023-09-27 18:29:32',	'2023-09-27 18:29:32'),
