(3383,	'App\\User',	3,	'created',	'App\\Track',	1707,	'[]',	'{\"artists\":\"Dariya Letto\",\"name\":\"No Time\",\"mix_name\":\"Original Mix\",\"remixers\":\"[\\\"\\\"]\",\"composer\":\"KEBA DARIA MYKOLAEVNA\",\"isrc\":\"UA-CT1-23-00044\",\"genre\":\"Orchestral, Cinematic\",\"youtube\":null,\"bpm\":null,\"length\":null,\"beatport_id\":null,\"beatport_slug\":null,\"beatport_release_id\":null,\"beatport_wave\":null,\"beatport_sample\":null,\"beatport_sample_start\":null,\"beatport_sample_end\":null,\"id\":1707}',	'https://cts-label.com/cts-admin/tracks',	'109.95.53.115',	'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/109.0.0.0 Safari/537.36',	NULL,	'2023-11-20 19:56:54',	'2023-11-20 19:56:54'),
(3384,	'App\\User',	3,	'created',	'App\\Release',	1880,	'[]',	'{\"tracklist_show_artist\":\"1\",\"tracklist_show_title\":\"1\",\"tracklist_show_mix\":\"0\",\"visible\":true,\"title\":\"Dariya Letto - Autumn\",\"genre\":\"Orchestral, Cinematic\",\"release_number\":\"CPR002233\",\"exclusive_period\":\"No Exclusive Period\",\"beatport\":null,\"youtube\":null,\"tracklist_show_custom\":\"0\",\"tracklist\":null,\"description_en\":\"<p>With the \\\"Autumn\\\" EP we continue to release the cinematic melodies of Ukrainian composer Daria Letto. Four completely new works, like short musical stories, have different moods and create a holistic impression of the mini-album. All of them are painted with shades of the passing autumn season. Sound as always, symphonic and emotional, sometimes slightly supplemented by synthesizers and electric guitar parts.<\\/p>\",\"description_ru\":\"<p>\\u0421 \\u00abAutumn\\u00bb EP \\u043c\\u044b \\u043f\\u0440\\u043e\\u0434\\u043e\\u043b\\u0436\\u0430\\u0435\\u043c \\u0432\\u044b\\u043f\\u0443\\u0441\\u043a\\u0430\\u0442\\u044c \\u043a\\u0438\\u043d\\u0435\\u043c\\u0430\\u0442\\u043e\\u0433\\u0440\\u0430\\u0444\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043c\\u0435\\u043b\\u043e\\u0434\\u0438\\u0438 \\u0443\\u043a\\u0440\\u0430\\u0438\\u043d\\u0441\\u043a\\u043e\\u0433\\u043e \\u043a\\u043e\\u043c\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0430 Daria Letto. \\u0427\\u0435\\u0442\\u044b\\u0440\\u0435 \\u0441\\u043e\\u0432\\u0435\\u0440\\u0448\\u0435\\u043d\\u043d\\u043e \\u043d\\u043e\\u0432\\u044b\\u0445 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u0435\\u0434\\u0435\\u043d\\u0438\\u044f, \\u0441\\u043b\\u043e\\u0432\\u043d\\u043e \\u043a\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438\\u0435 \\u043c\\u0443\\u0437\\u044b\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0440\\u0430\\u0441\\u0441\\u043a\\u0430\\u0437\\u044b, \\u0438\\u043c\\u0435\\u044e\\u0442 \\u0440\\u0430\\u0437\\u043d\\u043e\\u0435 \\u043d\\u0430\\u0441\\u0442\\u0440\\u043e\\u0435\\u043d\\u0438\\u0435 \\u0438 \\u0441\\u043e\\u0437\\u0434\\u0430\\u044e\\u0442 \\u0446\\u0435\\u043b\\u043e\\u0441\\u0442\\u043d\\u043e\\u0435 \\u0432\\u043f\\u0435\\u0447\\u0430\\u0442\\u043b\\u0435\\u043d\\u0438\\u0435 \\u043e\\u0442 \\u043c\\u0438\\u043d\\u0438-\\u0430\\u043b\\u044c\\u0431\\u043e\\u043c\\u0430. \\u0412\\u0441\\u0435 \\u043e\\u043d\\u0438 \\u043e\\u043a\\u0440\\u0430\\u0448\\u0435\\u043d\\u044b \\u043e\\u0442\\u0442\\u0435\\u043d\\u043a\\u0430\\u043c\\u0438 \\u0443\\u0445\\u043e\\u0434\\u044f\\u0449\\u0435\\u0433\\u043e \\u043e\\u0441\\u0435\\u043d\\u043d\\u0435\\u0433\\u043e \\u0441\\u0435\\u0437\\u043e\\u043d\\u0430. \\u0417\\u0432\\u0443\\u0447\\u0430\\u043d\\u0438\\u0435 \\u043a\\u0430\\u043a \\u0432\\u0441\\u0435\\u0433\\u0434\\u0430 \\u0441\\u0438\\u043c\\u0444\\u043e\\u043d\\u0438\\u0447\\u043d\\u043e\\u0435 \\u0438 \\u044d\\u043c\\u043e\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435, \\u0438\\u043d\\u043e\\u0433\\u0434\\u0430 \\u0441\\u043b\\u0435\\u0433\\u043a\\u0430 \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u043e \\u043f\\u0430\\u0440\\u0442\\u0438\\u044f\\u043c\\u0438 \\u0441\\u0438\\u043d\\u0442\\u0435\\u0437\\u0430\\u0442\\u043e\\u0440\\u043e\\u0432 \\u0438 \\u044d\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u0433\\u0438\\u0442\\u0430\\u0440.<\\/p>\",\"description_ua\":\"<p>\\u0417 \\u043c\\u0456\\u043d\\u0456-\\u0430\\u043b\\u044c\\u0431\\u043e\\u043c\\u043e\\u043c \\u00abAutumn\\u00bb \\u043c\\u0438 \\u043f\\u0440\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0454\\u043c\\u043e \\u0432\\u0438\\u0434\\u0430\\u0432\\u0430\\u0442\\u0438 \\u043a\\u0456\\u043d\\u0435\\u043c\\u0430\\u0442\\u043e\\u0433\\u0440\\u0430\\u0444\\u0456\\u0447\\u043d\\u0456 \\u043c\\u0435\\u043b\\u043e\\u0434\\u0456\\u0457 \\u0443\\u043a\\u0440\\u0430\\u0457\\u043d\\u0441\\u044c\\u043a\\u043e\\u0457 \\u043a\\u043e\\u043c\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u043a\\u0438 Daria Letto. \\u0427\\u0